/**
 * Knowledge library manager: upload, list and delete the course's tutor material, polling the
 * documents that are still being indexed. Requests go to knowledge_ajax.php (Moodle session +
 * sesskey), which signs the X-Moodle-Assertion headers for the backend.
 *
 * @module     local_libiac/knowledge_manager
 */
define("local_libiac/knowledge_manager", [], function() {
    var POLL_MS = 3000;
    var ACTIVE = ['pending', 'processing'];
    var BADGES = {
        pending: 'secondary',
        processing: 'info',
        indexed: 'success',
        error: 'danger'
    };

    var init = function(config) {
        var root = document.querySelector('[data-region="local_libiac-knowledge"]');
        if (!root) {
            return;
        }
        var strings = config.strings;
        var form = root.querySelector('[data-region="upload-form"]');
        var fileInput = form.querySelector('input[type="file"]');
        var submit = form.querySelector('[data-action="upload"]');
        var message = root.querySelector('[data-region="message"]');
        var rows = root.querySelector('[data-region="rows"]');
        var empty = root.querySelector('[data-region="empty"]');
        var timer = null;
        var settingsForm = root.querySelector('[data-region="settings-form"]');
        var settingsMessage = root.querySelector('[data-region="settings-message"]');
        var settingsSave = root.querySelector('[data-action="save-settings"]');

        var setMessage = function(text, isError) {
            message.textContent = text || '';
            message.className = 'mt-2 mb-0 ' + (isError ? 'text-danger' : 'text-success');
        };

        var errorText = function(key) {
            return strings['knowledge_error_' + key] || strings.knowledge_error_unavailable;
        };

        var request = function(action, options, extra) {
            var url = config.ajaxurl + '?action=' + action + '&courseid=' + config.courseid +
                '&sesskey=' + encodeURIComponent(config.sesskey) + (extra || '');
            return fetch(url, Object.assign({credentials: 'same-origin'}, options || {}))
                .then(function(response) {
                    return response.json().catch(function() {
                        return {error: 'unavailable'};
                    }).then(function(data) {
                        if (!response.ok || data.error) {
                            throw {key: data.error || 'unavailable'};
                        }
                        return data;
                    });
                }, function() {
                    throw {key: 'unavailable'};
                });
        };

        var cell = function(row, text) {
            var td = document.createElement('td');
            td.textContent = text;
            row.appendChild(td);
            return td;
        };

        // Everything is written with textContent: file names and messages are never parsed as HTML.
        var renderRow = function(doc) {
            var row = document.createElement('tr');
            cell(row, doc.filename);
            cell(row, doc.access_level === 'teacher_only' ? strings.knowledge_teacher : strings.knowledge_student);
            var created = new Date(doc.created_at);
            cell(row, isNaN(created) ? '' : created.toLocaleString());
            cell(row, String(doc.chunk_count));

            var statusCell = document.createElement('td');
            var badge = document.createElement('span');
            var color = BADGES[doc.status] || 'secondary';
            badge.className = 'badge badge-' + color + ' bg-' + color;
            badge.textContent = strings['status_' + doc.status] || doc.status;
            statusCell.appendChild(badge);
            if (doc.status === 'error' && doc.error_message) {
                var detail = document.createElement('div');
                detail.className = 'small text-muted';
                detail.textContent = doc.error_message;
                statusCell.appendChild(detail);
            }
            row.appendChild(statusCell);

            var actions = document.createElement('td');
            var del = document.createElement('button');
            del.type = 'button';
            del.className = 'btn btn-sm btn-outline-danger';
            del.textContent = strings.knowledge_delete;
            del.setAttribute('aria-label', strings.knowledge_delete + ': ' + doc.filename);
            del.addEventListener('click', function() {
                removeDocument(doc);
            });
            actions.appendChild(del);
            row.appendChild(actions);
            return row;
        };

        var render = function(documents) {
            rows.textContent = '';
            documents.forEach(function(doc) {
                rows.appendChild(renderRow(doc));
            });
            empty.hidden = documents.length > 0;
        };

        // Lists the documents and, while any is still being indexed, asks again every 3 seconds.
        var refresh = function() {
            clearTimeout(timer);
            return request('list').then(function(data) {
                render(data.documents);
                var busy = data.documents.some(function(doc) {
                    return ACTIVE.indexOf(doc.status) !== -1;
                });
                if (busy) {
                    timer = setTimeout(refresh, POLL_MS);
                }
            }).catch(function(error) {
                setMessage(errorText(error.key), true);
            });
        };

        var removeDocument = function(doc) {
            if (!window.confirm(strings.knowledge_confirmdelete + ' ' + doc.filename)) {
                return;
            }
            var body = new FormData();
            body.append('id', doc.id);
            request('delete', {method: 'POST', body: body}).then(function() {
                setMessage(strings.knowledge_deleted, false);
                return refresh();
            }).catch(function(error) {
                setMessage(errorText(error.key), true);
            });
        };

        // Pedagogical settings of the course: loaded once, saved with a PUT to the backend (signed server-side).
        var setSettingsMessage = function(text, isError) {
            settingsMessage.textContent = text || '';
            settingsMessage.className = 'mt-2 mb-0 ' + (isError ? 'text-danger' : 'text-success');
        };

        var showSettings = function(settings) {
            var radio = settingsForm.querySelector('input[name="pedagogical_mode"][value="' + settings.pedagogical_mode + '"]');
            if (radio) {
                radio.checked = true;
            }
            settingsForm.querySelector('select[name="depth_level"]').value = settings.depth_level;
            settingsForm.querySelector('input[name="formative_assessment"]').checked = !!settings.formative_assessment_enabled;
        };

        request('getsettings').then(function(data) {
            showSettings(data.settings);
        }).catch(function(error) {
            setSettingsMessage(errorText(error.key), true);
        });

        settingsForm.addEventListener('submit', function(event) {
            event.preventDefault();
            var body = new FormData();
            var mode = settingsForm.querySelector('input[name="pedagogical_mode"]:checked');
            body.append('pedagogical_mode', mode ? mode.value : 'mixed');
            body.append('depth_level', settingsForm.querySelector('select[name="depth_level"]').value);
            body.append('formative_assessment', settingsForm.querySelector('input[name="formative_assessment"]').checked ? '1' : '0');
            settingsSave.disabled = true;
            setSettingsMessage(strings.settings_saving, false);
            request('savesettings', {method: 'POST', body: body}).then(function(data) {
                showSettings(data.settings);
                setSettingsMessage(strings.settings_saved, false);
            }).catch(function(error) {
                setSettingsMessage(errorText(error.key), true);
            }).then(function() {
                settingsSave.disabled = false;
            });
        });

        // Teacher dashboard: aggregated metrics only. Everything is drawn with textContent / <progress>.
        var analytics = root.querySelector('[data-region="analytics"]');

        var fill = function(template, values) {
            return Object.keys(values).reduce(function(text, key) {
                return text.split('{$a->' + key + '}').join(String(values[key]));
            }, template);
        };

        var pct = function(rate) {
            return Math.round(rate * 100) + '%';
        };

        var el = function(tag, className, text) {
            var node = document.createElement(tag);
            if (className) {
                node.className = className;
            }
            if (text !== undefined) {
                node.textContent = text;
            }
            return node;
        };

        var bar = function(rate, kind) {
            var meter = document.createElement('progress');
            meter.className = 'local_libiac-bar local_libiac-bar-' + kind;
            meter.max = 100;
            meter.value = Math.round(rate * 100);
            meter.setAttribute('aria-label', pct(rate));
            meter.textContent = pct(rate);
            return meter;
        };

        var card = function(title, value, detail) {
            var col = el('div', 'col-md-4 mb-2');
            var box = el('div', 'card card-body h-100');
            box.appendChild(el('div', 'text-muted small', title));
            box.appendChild(el('div', 'h3 mb-1', value));
            box.appendChild(el('div', 'small', detail));
            col.appendChild(box);
            return col;
        };

        var renderAnalytics = function(data) {
            var q = data.qualitative;
            var n = data.quantitative;
            var cards = analytics.querySelector('[data-region="analytics-cards"]');
            cards.textContent = '';
            cards.appendChild(card(strings.analytics_active, String(n.active_students),
                fill(strings.analytics_active_detail, {active: n.active_students, total: n.students_in_cohort, days: n.window_days})));
            cards.appendChild(card(strings.analytics_onboarding, pct(n.onboarding_rate),
                fill(strings.analytics_onboarding_detail, {done: n.onboarding_completed, total: n.students_in_cohort})));
            var kinds = q.formative_activities.by_type.map(function(row) {
                return (strings['analytics_activity_' + row.type] || row.type) + ': ' + row.count;
            }).join(' · ');
            cards.appendChild(card(strings.analytics_activities, q.available ? String(q.formative_activities.total) : '-',
                kinds || strings.analytics_activities_detail));

            analytics.querySelector('[data-region="analytics-hidden"]').hidden = q.available;
            analytics.querySelector('[data-region="analytics-qualitative"]').hidden = !q.available;

            var struggling = analytics.querySelector('[data-region="analytics-struggling"]');
            struggling.textContent = '';
            var mastered = analytics.querySelector('[data-region="analytics-mastered"]');
            mastered.textContent = '';
            if (q.available) {
                if (!q.struggling_concepts.length) {
                    struggling.appendChild(el('li', 'text-muted', strings.analytics_none));
                }
                q.struggling_concepts.forEach(function(item, index) {
                    var li = el('li', 'mb-2');
                    var label = el('div');
                    label.appendChild(el('span', 'badge badge-' + (index < 3 ? 'danger' : 'warning') + ' bg-' + (index < 3 ? 'danger' : 'warning'), String(index + 1)));
                    label.appendChild(el('strong', 'ml-2 ms-2', item.concept));
                    label.appendChild(el('span', 'text-muted small ml-2 ms-2', item.students + ' · ' + pct(item.rate)));
                    li.appendChild(label);
                    li.appendChild(bar(item.rate, 'warn'));
                    struggling.appendChild(li);
                });
                if (!q.comprehended_concepts.length) {
                    var emptyRow = el('tr');
                    var emptyCell = el('td', 'text-muted', strings.analytics_none);
                    emptyCell.colSpan = 3;
                    emptyRow.appendChild(emptyCell);
                    mastered.appendChild(emptyRow);
                }
                q.comprehended_concepts.forEach(function(item) {
                    var row = el('tr');
                    row.appendChild(el('td', '', item.concept));
                    row.appendChild(el('td', '', String(item.students)));
                    var share = el('td');
                    share.appendChild(bar(item.rate, 'ok'));
                    share.appendChild(el('span', 'small ml-2 ms-2', pct(item.rate)));
                    row.appendChild(share);
                    mastered.appendChild(row);
                });
            }
            analytics.querySelector('[data-region="analytics-usage"]').textContent =
                fill(strings.analytics_messages, {}).split('{$a}').join(String(n.window_days)) + ': ' + n.messages_in_window;
            analytics.querySelector('[data-region="analytics-message"]').hidden = true;
            analytics.querySelector('[data-region="analytics-body"]').hidden = false;
        };

        request('getanalytics').then(function(data) {
            renderAnalytics(data.analytics);
        }).catch(function(error) {
            analytics.querySelector('[data-region="analytics-message"]').textContent = errorText(error.key);
        });

        form.addEventListener('submit', function(event) {
            event.preventDefault();
            if (!fileInput.files.length) {
                setMessage(strings.knowledge_nofile, true);
                return;
            }
            submit.disabled = true;
            setMessage(strings.knowledge_uploading, false);
            request('upload', {method: 'POST', body: new FormData(form)}).then(function() {
                setMessage(strings.knowledge_uploaded, false);
                form.reset();
                return refresh();
            }).catch(function(error) {
                setMessage(errorText(error.key), true);
            }).then(function() {
                submit.disabled = false;
            });
        });

        refresh();
    };

    return {init: init};
});
